 ALTER TABLE tenant ADD COLUMN IF NOT EXISTS is_demo BOOLEAN NOT NULL DEFAULT FALSE;
-- Exact UUIDs generated by the legacy demo seed; never classify by display name or code alone.
UPDATE tenant t SET is_demo=TRUE FROM (VALUES
    ('20a1effd-0363-322f-97a5-b07a1a1854e7'::uuid,'SYNERA'),
    ('096dc0c4-30ba-359a-a4ac-18b55fe2a2d0'::uuid,'SUOI_VIET'),
    ('2db0151d-b2e5-3900-911f-a9a4cf8816b6'::uuid,'MINH_PHAT'),
    ('9bd3b03c-818e-3e14-a79f-208c5b3c19e1'::uuid,'AN_KHANG'),
    ('e8f909a8-67db-3b91-aaa7-677ab3bde2e1'::uuid,'TAP_HOA_LAN'),
    ('27dcb11e-1111-38c6-b600-0c3ebbaa3125'::uuid,'QUAN_BINH'),
    ('4d44f893-0ef8-334e-9588-20f715780af8'::uuid,'CAFE_24')
) AS legacy(id,code) WHERE t.id=legacy.id AND t.code=legacy.code;
CREATE INDEX IF NOT EXISTS tenant_demo_idx ON tenant (is_demo, tenant_type);
CREATE TABLE IF NOT EXISTS demo_cleanup_log (
    id UUID PRIMARY KEY,
    executed_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    tenant_codes JSONB NOT NULL,
    row_counts JSONB NOT NULL,
    requested_by VARCHAR(200) NOT NULL
);
ALTER TABLE app_users ADD COLUMN IF NOT EXISTS username VARCHAR(120);
CREATE UNIQUE INDEX IF NOT EXISTS app_users_tenant_username_idx
    ON app_users (tenant_id, lower(username)) WHERE username IS NOT NULL;
ALTER TABLE product ADD COLUMN IF NOT EXISTS category VARCHAR(120) NOT NULL DEFAULT '',
    ADD COLUMN IF NOT EXISTS note TEXT NOT NULL DEFAULT '';
ALTER TABLE outlet ADD COLUMN IF NOT EXISTS outlet_type VARCHAR(80) NOT NULL DEFAULT '';

CREATE TABLE IF NOT EXISTS npp_profile (
    tenant_id UUID NOT NULL REFERENCES tenant(id),
    npp_tenant_id UUID NOT NULL REFERENCES tenant(id),
    org_unit_id UUID REFERENCES org_unit(id),
    address TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (tenant_id, npp_tenant_id)
);

CREATE TABLE IF NOT EXISTS foundation_import_batch (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenant(id),
    import_kind VARCHAR(24) NOT NULL,
    file_name VARCHAR(255) NOT NULL,
    file_sha256 CHAR(64) NOT NULL,
    status VARCHAR(16) NOT NULL DEFAULT 'PREVIEWED' CHECK (status IN ('PREVIEWED', 'COMMITTED')),
    row_count INTEGER NOT NULL DEFAULT 0 CHECK (row_count >= 0),
    error_count INTEGER NOT NULL DEFAULT 0 CHECK (error_count >= 0),
    warning_count INTEGER NOT NULL DEFAULT 0 CHECK (warning_count >= 0),
    created_count INTEGER NOT NULL DEFAULT 0 CHECK (created_count >= 0),
    updated_count INTEGER NOT NULL DEFAULT 0 CHECK (updated_count >= 0),
    unchanged_count INTEGER NOT NULL DEFAULT 0 CHECK (unchanged_count >= 0),
    created_by UUID NOT NULL REFERENCES app_users(id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    committed_at TIMESTAMPTZ,
    reason VARCHAR(500) NOT NULL DEFAULT '',
    UNIQUE (tenant_id, id)
);
CREATE INDEX IF NOT EXISTS foundation_import_batch_scope_idx
    ON foundation_import_batch (tenant_id, created_by, created_at DESC);
CREATE TABLE IF NOT EXISTS foundation_import_row (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenant(id),
    batch_id UUID NOT NULL,
    sheet_name VARCHAR(40) NOT NULL,
    line_number INTEGER NOT NULL,
    row_data JSONB NOT NULL,
    errors JSONB NOT NULL DEFAULT '[]'::jsonb,
    warnings JSONB NOT NULL DEFAULT '[]'::jsonb,
    operation VARCHAR(16) NOT NULL DEFAULT 'CREATE',
    UNIQUE (batch_id, sheet_name, line_number),
    FOREIGN KEY (tenant_id, batch_id) REFERENCES foundation_import_batch (tenant_id, id)
);
CREATE TABLE IF NOT EXISTS foundation_import_identity (
    tenant_id UUID NOT NULL REFERENCES tenant(id),
    sheet_name VARCHAR(40) NOT NULL,
    business_key VARCHAR(300) NOT NULL,
    target_id UUID NOT NULL,
    payload_hash CHAR(64) NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (tenant_id, sheet_name, business_key)
);

INSERT INTO permission (code, module, description, sensitive, phase)
VALUES ('foundation:import', 'Nhập dữ liệu nền', 'Nhập dữ liệu nền trong phạm vi tenant', TRUE, 'P5')
ON CONFLICT (code) DO UPDATE SET sensitive = TRUE;
INSERT INTO role_permission (role_code, permission_code, scope_code)
SELECT code, 'foundation:import', 'A' FROM role
WHERE code IN ('NSX_ADMIN', 'NPP_OWNER', 'NPP_STAFF')
ON CONFLICT (role_code, permission_code) DO NOTHING;
